'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) {
    throw new TypeError('diffLines expects two arrays of strings');
  }
  const n = a.length;
  const m = b.length;

  // Intern lines as integers so the inner loops compare numbers.
  const ids = new Map();
  const A = new Int32Array(n);
  const B = new Int32Array(m);
  for (let i = 0; i < n; i++) {
    let id = ids.get(a[i]);
    if (id === undefined) { id = ids.size; ids.set(a[i], id); }
    A[i] = id;
  }
  for (let j = 0; j < m; j++) {
    let id = ids.get(b[j]);
    if (id === undefined) { id = ids.size; ids.set(b[j], id); }
    B[j] = id;
  }

  // Raw script: codes 0 = equal, 1 = delete, 2 = insert, in path order.
  const codes = [];
  const size = n + m + 2;
  const vf = new Int32Array(2 * size + 1);
  const vb = new Int32Array(2 * size + 1);
  myers(A, 0, n, B, 0, m, vf, vb, size, codes);

  // Emit; inside each run without equals, all deletes precede all inserts.
  const out = [];
  let i = 0;
  let j = 0;
  let k = 0;
  while (k < codes.length) {
    if (codes[k] === 0) {
      out.push({ op: 'equal', line: a[i++] });
      j++;
      k++;
      continue;
    }
    let dels = 0;
    let ins = 0;
    for (; k < codes.length && codes[k] !== 0; k++) {
      if (codes[k] === 1) dels++; else ins++;
    }
    for (; dels > 0; dels--) out.push({ op: 'delete', line: a[i++] });
    for (; ins > 0; ins--) out.push({ op: 'insert', line: b[j++] });
  }
  return out;
}

/**
 * Linear-space Myers diff of A[aLo, aHi) against B[bLo, bHi), appending codes.
 * vf/vb are shared scratch diagonals indexed by k + off.
 */
function myers(A, aLo, aHi, B, bLo, bHi, vf, vb, off, codes) {
  // Common prefix.
  const pre = aLo;
  while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) { aLo++; bLo++; }
  for (let p = pre; p < aLo; p++) codes.push(0);
  // Common suffix (emitted after the middle).
  let suffix = 0;
  while (aLo < aHi && bLo < bHi && A[aHi - 1] === B[bHi - 1]) { aHi--; bHi--; suffix++; }

  if (aLo === aHi) {
    for (let q = bLo; q < bHi; q++) codes.push(2);
  } else if (bLo === bHi) {
    for (let p = aLo; p < aHi; p++) codes.push(1);
  } else {
    const s = middleSnake(A, aLo, aHi, B, bLo, bHi, vf, vb, off);
    myers(A, aLo, aLo + s.x0, B, bLo, bLo + s.y0, vf, vb, off, codes);
    for (let p = s.x0; p < s.x1; p++) codes.push(0);
    myers(A, aLo + s.x1, aHi, B, bLo + s.y1, bHi, vf, vb, off, codes);
  }

  for (; suffix > 0; suffix--) codes.push(0);
}

/**
 * Find the middle snake (local coordinates) of a minimal path. Requires both
 * ranges nonempty with differing first and last elements.
 */
function middleSnake(A, aLo, aHi, B, bLo, bHi, vf, vb, off) {
  const N = aHi - aLo;
  const M = bHi - bLo;
  const delta = N - M;
  const odd = (delta & 1) !== 0;
  const max = (N + M + 1) >> 1;
  vf[off + 1] = 0;
  vb[off + 1] = 0;
  for (let d = 0; d <= max; d++) {
    // Forward pass.
    for (let k = -d; k <= d; k += 2) {
      let x = (k === -d || (k !== d && vf[off + k - 1] < vf[off + k + 1]))
        ? vf[off + k + 1]
        : vf[off + k - 1] + 1;
      let y = x - k;
      const x0 = x;
      const y0 = y;
      while (x < N && y < M && A[aLo + x] === B[bLo + y]) { x++; y++; }
      vf[off + k] = x;
      const kr = delta - k;
      if (odd && kr >= -(d - 1) && kr <= d - 1 && x + vb[off + kr] >= N) {
        return { x0, y0, x1: x, y1: y };
      }
    }
    // Reverse pass, in reversed coordinates.
    for (let k = -d; k <= d; k += 2) {
      let x = (k === -d || (k !== d && vb[off + k - 1] < vb[off + k + 1]))
        ? vb[off + k + 1]
        : vb[off + k - 1] + 1;
      let y = x - k;
      const x0 = x;
      const y0 = y;
      while (x < N && y < M && A[aHi - 1 - x] === B[bHi - 1 - y]) { x++; y++; }
      vb[off + k] = x;
      const kf = delta - k;
      if (!odd && kf >= -d && kf <= d && x + vf[off + kf] >= N) {
        return { x0: N - x, y0: M - y, x1: N - x0, y1: M - y0 };
      }
    }
  }
  throw new Error('diffLines: middle snake not found');
