'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Int32Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--)
    dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp[0][0];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', '-x', '+y', ' z', 'a', 'b'];
function gen() { const n = rnd(14); return Array.from({ length: n }, () => alpha[rnd(alpha.length)]); }

for (let t = 0; t < 30000; t++) {
  const a = gen();
  const b = rnd(3) === 0 ? a.map((s) => (rnd(4) ? s : alpha[rnd(alpha.length)])) : gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const edits = s.filter((e) => e.op !== 'equal').length;
  assert.equal(edits, a.length + b.length - 2 * lcs(a, b));
  for (let k = 1; k < s.length; k++) assert.ok(!(s[k - 1].op === 'insert' && s[k].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3, 5]) {
    const h = unifiedHunks(a, b, { context });
    if (edits === 0) assert.deepEqual(h, []);
    assert.deepEqual(applyHunks(a, h), b);
    for (const x of h) {
      assert.equal(x.lines.length > 0, true);
    }
    for (let k = 1; k < h.length; k++) {
      const prevEnd = h[k - 1].oldLines ? h[k - 1].oldStart - 1 + h[k - 1].oldLines : h[k - 1].oldStart;
      const start = h[k].oldLines ? h[k].oldStart - 1 : h[k].oldStart;
      assert.ok(start - prevEnd >= 1, 'gap');
    }
    if (h.length > 1) {
      // Changed-region gap between hunks: count equal lines between adjacent hunks' change cores.
      for (let k = 1; k < h.length; k++) {
        const tail = h[k - 1].lines; let t = 0; while (t < tail.length && tail[tail.length - 1 - t][0] === ' ') t++;
        const head = h[k].lines; let u = 0; while (u < head.length && head[u][0] === ' ') u++;
        const prevEnd = h[k - 1].oldLines ? h[k - 1].oldStart - 1 + h[k - 1].oldLines : h[k - 1].oldStart;
        const start = h[k].oldLines ? h[k].oldStart - 1 : h[k].oldStart;
        assert.ok(t + u + (start - prevEnd) > 2 * context, 'unmerged gap too small');
        assert.equal(t, context); assert.equal(u, context);
      }
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// Zero-range coordinates.
assert.deepEqual(unifiedHunks(['a'], ['n', 'a'], { context: 0 }), [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+n'] }]);
assert.deepEqual(unifiedHunks(['d', 'a'], ['a'], { context: 0 }), [{ oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-d'] }]);
assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'n', 'b'], { context: 0 }), [{ oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+n'] }]);
assert.deepEqual(unifiedHunks([], [], {}), []);
assert.throws(() => applyHunks(['a'], [{ oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' b'] }]), /hunk 0 does not apply/);
const h2 = unifiedHunks(['a','b','c','d','e','f','g','h','i'], ['A','b','c','d','e','f','g','h','I'], { context: 1 });
assert.throws(() => applyHunks(['a','b','c','d','e','f','g','h','j'], h2), /hunk 1 does not apply/);
assert.throws(() => applyHunks(['a','b','c','d','e','f','g','h','i'], [h2[1], h2[0]]), /hunk 1 does not apply/);

// Performance.
const big = Array.from({ length: 20000 }, (_, i) => `line ${i % 50}`);
const big2 = big.slice(); big2[100] = 'X'; big2.splice(15000, 3); big2.splice(7000, 0, 'Y', 'Z');
let t0 = performance.now(); const d = diffLines(big, big2); const h = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, h), big2);
console.log('small change 20k:', (performance.now() - t0).toFixed(1), 'ms', d.length);
t0 = performance.now(); diffLines(big, big.slice()); console.log('identical 20k:', (performance.now() - t0).toFixed(1), 'ms');
const rep = Array(20000).fill('same'); const rep2 = rep.slice(); rep2.splice(10000, 1, 'other');
t0 = performance.now(); assert.deepEqual(applyHunks(rep, unifiedHunks(rep, rep2)), rep2); console.log('repetitive 20k:', (performance.now() - t0).toFixed(1), 'ms');
const r1 = Array.from({ length: 4000 }, () => alpha[rnd(alpha.length)]), r2 = Array.from({ length: 4000 }, () => alpha[rnd(alpha.length)]);
t0 = performance.now(); const e = diffLines(r1, r2).filter((x) => x.op !== 'equal').length; console.log('random 4k:', (performance.now() - t0).toFixed(1), 'ms');
assert.equal(e, 8000 - 2 * lcs(r1, r2));
console.log('ok');
